<?php
require_once __DIR__.'/../app/bootstrap.php'; require_login();
$user=current_user(); $pdo=db(); $q=trim((string)($_GET['q']??'')); $status=(string)($_GET['status']??'');
$where=[]; $params=[];
if ($user['role']!=='system_admin') { if (!$user['cooperative_id']) { $where[]='1=0'; } else { $where[]='m.cooperative_id=?'; $params[]=(int)$user['cooperative_id']; } }
if ($q!=='') { $where[]='(m.first_name LIKE ? OR m.last_name LIKE ? OR m.member_number LIKE ? OR m.phone LIKE ? OR m.email LIKE ?)'; $like='%'.$q.'%'; array_push($params,$like,$like,$like,$like,$like); }
if (in_array($status,['active','inactive','suspended'],true)) { $where[]='m.status=?'; $params[]=$status; }
$sql='SELECT m.*, c.name AS cooperative_name FROM members m JOIN cooperatives c ON c.id=m.cooperative_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY m.created_at DESC LIMIT 500'; $st=$pdo->prepare($sql); $st->execute($params); $members=$st->fetchAll();
$pageTitle='Member management'; require __DIR__.'/includes/header.php';
?><div class="welcome-row"><div><h2>Members directory</h2><p class="muted">Search, review, and maintain cooperative member records.</p></div><a class="btn primary" href="member-form.php">＋ Add member</a></div><section class="panel"><form class="filters" method="get"><div class="search-field"><span>⌕</span><input type="search" name="q" placeholder="Search name, number, phone or email" value="<?= e($q) ?>"></div><select name="status" aria-label="Filter by status"><option value="">All statuses</option><?php foreach(['active','inactive','suspended'] as $s): ?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach; ?></select><button class="btn secondary" type="submit">Filter</button><?php if($q!==''||$status!==''): ?><a class="btn ghost" href="members.php">Clear</a><?php endif; ?></form><div class="table-meta"><span><?= count($members) ?> record(s) shown</span><span>Maximum 500 records per view</span></div><?php if(!$members): ?><div class="empty-state"><div class="empty-icon">⌕</div><h3>No matching members</h3><p>Try a different search, or add a new member record.</p><a class="btn primary" href="member-form.php">Add member</a></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Member</th><th>Member number</th><th>Cooperative</th><th>Phone / email</th><th>Joined</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($members as $m): ?><tr><td><div class="person-cell"><span class="avatar small"><?= e(strtoupper(substr($m['first_name'],0,1).substr($m['last_name'],0,1))) ?></span><span><strong><?= e($m['first_name'].' '.$m['last_name']) ?></strong><small><?= e($m['sex']) ?></small></span></div></td><td><?= e($m['member_number']) ?></td><td><?= e($m['cooperative_name']) ?></td><td><?= e($m['phone'] ?: '—') ?><small class="subline"><?= e($m['email'] ?: '') ?></small></td><td><?= e($m['joined_on']) ?></td><td><span class="badge <?= e($m['status']) ?>"><?= e(ucfirst($m['status'])) ?></span></td><td><div class="action-row"><a class="icon-btn" title="Edit member" href="member-form.php?id=<?= (int)$m['id'] ?>">✎</a><?php if (in_array($user['role'], ['system_admin','cooperative_manager'], true)): ?><form method="post" action="actions/member-delete.php" data-confirm="Remove this member record? This cannot be undone."><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$m['id'] ?>"><button class="icon-btn danger-text" title="Delete member" type="submit">×</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php require __DIR__.'/includes/footer.php'; ?>
